export function UsageTable({ rows }: { rows: unknown[] }) {
  return (
    <Card>
      <DataTable rows={rows} />
    </Card>
  );
}

import { Card } from '@ds/react';
import styles from './UsageTable.module.css';

export function UsageTable({ rows }: { rows: { id: string; label: string }[] }) {
  return (
    <Card>
      <table className={styles.table}>
        <tbody>
          {rows.map((r) => (
            <tr key={r.id}>
              <td>{r.label}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </Card>
  );
}

.table {
  inline-size: 100%;
